# Atera: update Chainsaw on a Windows agent without downloading anything.
# Writes chainsaw.ps1 (hunt only, UTC time window) and sigma-update.ps1 (daily Sigma pull) from evtxripper main (2026-11-11),
# checks their SHA256, and registers the "Chainsaw Sigma Update" scheduled task. Run as SYSTEM.
$ErrorActionPreference = 'Stop'
$base = 'C:\Program Files\socfortress\chainsaw'
$bin  = 'C:\Program Files (x86)\ossec-agent\active-response\bin'
if (-not (Test-Path "$base\chainsaw.exe")) { Write-Output "NOT INSTALLED: $base\chainsaw.exe missing; run ChainsawInstall.ps1 first"; exit 2 }

function Put($b64, $path, $sha) {
    [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($b64))
    if ((Get-FileHash $path).Hash -ne $sha) { throw "hash mismatch on $path" }
    Write-Output "wrote $path"
}
Put '' "$bin\chainsaw.ps1" 'A06920AC72706395147C3DBA459DF1B7F372D203D171F045D7D8CBD9A2CEF3A0'
Put '' "$base\sigma-update.ps1" '77819924C8F0673DDCCB51C200387BA31C7BD9F6E707319DA440FAB47B29E1ED'

$a = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NoProfile -ExecutionPolicy Bypass -File `"$base\sigma-update.ps1`""
$t = New-ScheduledTaskTrigger -Daily -At 3am -RandomDelay (New-TimeSpan -Hours 2)
$p = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
$s = New-ScheduledTaskSettingsSet -StartWhenAvailable -ExecutionTimeLimit (New-TimeSpan -Minutes 30)
Register-ScheduledTask -TaskName 'Chainsaw Sigma Update' -Action $a -Trigger $t -Principal $p -Settings $s -Force | Out-Null
Write-Output 'registered task Chainsaw Sigma Update'

# Quick self-check: does chainsaw.exe start? (-1073741515 = Visual C++ runtime missing)
& "$base\chainsaw.exe" --version | Out-Null
Write-Output "chainsaw.exe --version exit code: $LASTEXITCODE"
